{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In a mouse PK study, the closest analogue sharing the identical pyrazolopyrimidine carboxamide core crossed the BBB with approximately 3-fold higher brain than plasma exposure, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The related cyclohexylamide/alkoxy radiotracer [11C]NE40 showed high brain uptake and washout in mice, rhesus monkey, and humans, demonstrating that this structural motif can achieve robust BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Structurally similar cyclohexylamide alkoxy tracers showed good mouse brain uptake (1.7–1.8% ID at 2 min), supporting brain penetration of the query's cyclohexylamide/ether motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "GSK620, a moderately similar amide, had a brain/plasma AUC ratio of 27.2% and was classified as adequate CNS penetration, supporting that this lipophilic amide class can achieve meaningful access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A lower-similarity pyrazolopyridinone benzamide showed low rat brain/plasma exposure (<0.08), but its different fused lactam core and lower transfer score limit its relevance to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. The closest analogue (C08) with the same pyrazolopyrimidine carboxamide showed ~3x brain/plasma exposure, and multiple related cyclohexylamide/alkoxy compounds (C07, C03) showed good brain uptake; the contradictory low-exposure records come from less similar scaffolds and do not override this pattern.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter involvement was not explicitly assessed for the query or closest analogue.",
    "Human CNS exposure data are not available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

